import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    if n == 0 or len(data) < 1:
        return

    numbers = list(map(int, data[1:1+n]))

    result = [x * x for x in numbers if (x * x) % 3 == 0]

    for val in result:
        print(val)

if __name__ == "__main__":
    main()
